%[text] # Krav 1 og 2: Kinematikk for Gruppebot (5 DOF, RRRRR)
%[text] Gruppe 4, ELE208. Fila bygger på vår første Krav2. Vi har fått hjelp av KI (Claude Opus 5.5, Anthropic) til figurer, simuleringer og finere utskrift, og til å skrive om koden så den passer sammen med Krav3.
%[text] Merking: \[KI\] = laget med KI. \[KI-endret\] = vår kode eller analyse, skrevet om eller endret med KI. Blokker uten merke har vi skrevet selv.
%%
%[text] ## Roboten (Gruppebot)
% Henter roboten (DH-tabell og tool) fra Gruppebot.mlx i samme mappe
Gruppebot %[output:9c620ee6]

% Rekkefølge: 1.i.2/2.i.1 FK, 1.ii.1 kamera, 2.i.3 IK, 2.i.2 Jacobi,
% 2.ii.1 kameraet styrer roboten, 2.i.4 baneplanlegging.
% Trenger Symbolic Math Toolbox. Kjøres før Krav3.
%%
%[text] ## Oppsett
% [KI-endret] Samme oppsett som i Krav3
M       = [1 1 1 0 1 1];                 % ikine-maske [x y z rx ry rz], rx tatt bort
q_gjett = deg2rad([0 -60 110 -50 0]);   % albue opp
vb      = [0 0.3 0];                     % båndfart [m/s] langs +y
ws      = [-0.6 1.6 -1.6 1.6 0 1.8];     % plotteområde [m]
vis     = [120 25];                      % synsvinkel [az el]

% Pose for griperen: posisjon p, eskas vinkel psi om z, griperen rett ned
pose = @(p, psi) SE3(p) * SE3.Rz(psi) * SE3.Rx(pi);

%%
%[text] ## 1.i.2 og 2.i.1 Foroverkinematikk uten toolbox
% [KI-endret] T04 for hånd (symbolsk), sjekket mot toolboxen
% A_i = Rz(theta)*Tz(d)*Tx(a)*Rx(alpha), samme DHmatrix som i SCARA-koden
% sym(pi) gir cos(-pi/2) = 0 eksakt i stedet for 6e-17
syms q1 q2 q3 q4 q5 real
syms d_1 a_2 a_3 d_5 real

DH(1) = struct('type','R', 'a',0,   'alpha',-sym(pi)/2, 'd',d_1, 'theta',q1);
DH(2) = struct('type','R', 'a',a_2, 'alpha',0,          'd',0,   'theta',q2);
DH(3) = struct('type','R', 'a',a_3, 'alpha',0,          'd',0,   'theta',q3);
DH(4) = struct('type','R', 'a',0,   'alpha',-sym(pi)/2, 'd',0,   'theta',q4);
DH(5) = struct('type','R', 'a',0,   'alpha',0,          'd',d_5, 'theta',q5);

DHmatrix = @(p) [ ...
    cos(p.theta), -sin(p.theta)*cos(p.alpha),  sin(p.theta)*sin(p.alpha), p.a*cos(p.theta);
    sin(p.theta),  cos(p.theta)*cos(p.alpha), -cos(p.theta)*sin(p.alpha), p.a*sin(p.theta);
    0,             sin(p.alpha),               cos(p.alpha),              p.d;
    0,             0,                          0,                         1];

A1 = DHmatrix(DH(1));  A2 = DHmatrix(DH(2));  A3 = DHmatrix(DH(3));
A4 = DHmatrix(DH(4));  A5 = DHmatrix(DH(5));

T04 = simplify(A1*A2*A3*A4)          % 1.i.2 %[output:2de8e913]
p04 = T04(1:3,4)                     % 2-leddsarm i planet, dreid med q1 %[output:697b0fb0]

% 2.i.1: sammenlign med toolboxen for 100 tilfeldige leddvinkler
T04_tall = matlabFunction(subs(T04, [d_1 a_2 a_3], [d1 L1 L2]), 'Vars', {q1, q2, q3, q4});
avvik = 0;
for k = 1:100
    qr = (2*rand(1,5) - 1)*pi;
    T_haand   = T04_tall(qr(1), qr(2), qr(3), qr(4));
    T_toolbox = Gruppebot.A(1:4, qr).T;
    avvik = max(avvik, max(abs(T_haand(:) - T_toolbox(:))));
end
fprintf('Største avvik mellom T04 for hånd og toolbox: %.1e (bare avrunding)\n', avvik); %[output:2af81c5d]

% Hele roboten med verktøy ved q = 0 (strak arm)
T05     = simplify(T04*A5);
T_tcp0  = double(subs(T05, [q1 q2 q3 q4 q5 d_1 a_2 a_3 d_5], [0 0 0 0 0 d1 L1 L2 L3])) * transl(0.17, 0, 0.03);
T_fkine = Gruppebot.fkine([0 0 0 0 0]).T;
fprintf('TCP ved q = 0: hånd [%.2f %.2f %.2f], fkine [%.2f %.2f %.2f]\n', T_tcp0(1:3,4), T_fkine(1:3,4)); %[output:27e290da]
% skal gi [1.81 0 0.16] begge steder, med griperen rett ned

%%
%[text] ## 1.ii.1 Fra kamera til robot
% [KI-endret] Pinhole-modellen fra vår Krav2, nå med Rx(pi) som i Krav3 og tall for D455
% Kameraet henger 1.5 m over basen og 1 m oppstrøms. trotx(pi) snur z-aksen ned.
% Posegraf (kap. 2): {0} -> T_C -> {C} -> p_C -> eska
T_C = transl(1.0, -1.0, 1.5) * trotx(pi)            % 0T_C %[output:2a06459e]

p_ekte = [1.06; -1.0; 0.40];                         % toppen av eska i {0} (fasit)
p_C    = h2e(inv(T_C) * e2h(p_ekte))                 % det kameraet ser %[output:5662d6b1]
feil_C = [0.002; 0.0013; 0];                         % målefeil i {C}, innenfor +-5 mm
p_0    = h2e(T_C * e2h(p_C + feil_C))                % p0 = T_C * pC, med målefeil %[output:48c8858d]

% rotasjon endrer ikke lengden, så feilen er like stor i {0} og {C}
fprintf('Målefeil: %.2f mm i {C} og %.2f mm i {0}\n', 1000*norm(feil_C), 1000*norm(T_C(1:3,1:3)*feil_C)); %[output:1816c53c]

% Piksel -> {C} med pinhole-modellen. D455: 848 x 480, synsfelt 87 x 58 grader.
% Brennvidde i piksler: f = (halve bredden) / tan(halve synsvinkelen)
fx = 424/tand(87/2);  fy = 240/tand(58/2);           % 446.8 og 433.0 piksler
cx = 424;  cy = 240;                                 % bildesenter
Z  = 1.5 - 0.40;                                     % kamera til toppen av eska [m]
uv = [448 240];                                      % eksempelpiksel
p_C_px = [(uv(1) - cx)*Z/fx; (uv(2) - cy)*Z/fy; Z] %[output:2f1e9ccb]
p_0_px = h2e(T_C * e2h(p_C_px)) %[output:348704d4]
fprintf('Én piksel er %.1f x %.1f mm på eska (krav +-5 mm)\n', 1000*Z/fx, 1000*Z/fy); %[output:7796466f]
% avrunding til nærmeste piksel gir maks ca. 1.25 mm feil

%%
%[text] ## 2.i.3 Invers kinematikk og arbeidsområdet
% [KI-endret] ikine med maske. Masketesten er fra vår Krav3.
% 5 ledd kan bare styre 5 av 6 frihetsgrader. Vi tar bort rx (vipping sidelengs),
% som ikke trengs når griperen peker rett ned. psi = q1 - q5 er eskas retning.
punkt = [1.0 0.0 0.4;          % plukk, 1.0 m ut
         1.0 0.0 1.0;          % høyeste plukk, 1.0 m opp
         0.0 1.2 0.4];         % lengst ut, 1.2 m (drop opptil 1.2 m)
navn  = {'Plukk 1.0 m ut', 'Høyeste plukk', 'Lengst ut 1.2 m'};
gjett = [q_gjett; deg2rad([0 -85 90 -5 0]); deg2rad([98 -47 83 -36 98])];
q_ik  = zeros(3,5);
for k = 1:3 %[output:group:71806b35]
    q_ik(k,:) = Gruppebot.ikine(pose(punkt(k,:), 0), 'q0', gjett(k,:), 'mask', M);
    p_fk = Gruppebot.fkine(q_ik(k,:)).t';
    fprintf('%-17s q = [%6.1f %6.1f %6.1f %6.1f %6.1f] grader, fkine [%.2f %.2f %.2f], psi = %.1f grader\n', ... %[output:0af26e64]
            navn{k}, rad2deg(q_ik(k,:)), p_fk, rad2deg(q_ik(k,1) - q_ik(k,5))); %[output:0af26e64]
end %[output:group:71806b35]

% Hvorfor rx og ikke rz i maska? Uten rz kan ikine vri eska fritt.
q_rx = Gruppebot.ikine(pose([1.0 0.5 0.4], 0), 'q0', q_gjett, 'mask', [1 1 1 0 1 1]);
q_rz = Gruppebot.ikine(pose([1.0 0.5 0.4], 0), 'q0', q_gjett, 'mask', [1 1 1 1 1 0]);
fprintf('Eskas retning ved y = 0.5 m: %.1f grader med rx bort, %.1f grader med rz bort\n', ... %[output:group:6b59ad92] %[output:30f5c80e]
        rad2deg(q_rx(1) - q_rx(5)), rad2deg(q_rz(1) - q_rz(5))); %[output:group:6b59ad92] %[output:30f5c80e]

% [KI-endret] Analytisk IK fra vår ik_downward.m og oppgave_2i3, nå som funksjonen
% ik_analytisk nederst i fila, med eskas retning psi. Sammenlignes med ikine.
% Som 2-leddsarmen i Corke 7.2.1: q1 med atan2, q3 med cosinussetningen, q2 med atan2,
% og q4 = -(q2 + q3) holder griperen rett ned.
T_tool = SE3(Gruppebot.tool);
tx = T_tool.t(1);  tz = T_tool.t(3);                 % TCP 0.17 m ut og 0.03 m ned fra flensen
punkt_a = [punkt; 1.06 0.05 0.40];                   % + plukkpunktet fra 2.ii.1, eska vridd 30 grader
psi_a   = deg2rad([0 0 0 30]);
avvik_ik = 0;
for k = 1:size(punkt_a, 1) %[output:group:1f525332]
    q_ana = ik_analytisk(punkt_a(k,:), psi_a(k), L1, L2, d1, L3, tx, tz, +1);
    q0    = q_gjett;                                 % startgjett, q1 og q5 fra geometrien
    q0(1) = atan2(punkt_a(k,2) - tx*sin(psi_a(k)), punkt_a(k,1) - tx*cos(psi_a(k)));
    q0(5) = q0(1) - psi_a(k);
    q_num = Gruppebot.ikine(pose(punkt_a(k,:), psi_a(k)), 'q0', q0, 'mask', M);
    avvik_ik = max(avvik_ik, max(abs(rad2deg(q_ana - q_num))));
    fprintf('Analytisk IK i [%.2f %.2f %.2f], psi = %2.0f grader: [%s] grader, TCP-feil %.1e m\n', ... %[output:983e4e1f]
            punkt_a(k,:), rad2deg(psi_a(k)), sprintf('%7.1f', rad2deg(q_ana)), ... %[output:983e4e1f]
            norm(Gruppebot.fkine(q_ana).t' - punkt_a(k,:))); %[output:983e4e1f]
end %[output:group:1f525332]
fprintf('Største avvik mellom analytisk IK og ikine: %.1e grader\n', avvik_ik); %[output:661a9432]

% [KI] q3 = +-acos(D) gir to løsninger, albue opp og albue ned (Corke 7.2.1).
% Begge treffer punktet, men med albue ned havner albuen under basen.
q_opp   = ik_analytisk(punkt(1,:), 0, L1, L2, d1, L3, tx, tz, +1);
q_ned   = ik_analytisk(punkt(1,:), 0, L1, L2, d1, L3, tx, tz, -1);
z_albue = @(q) d1 - L1*sin(q(2));                    % høyden til albuen (ramme 2)
fprintf('Albue opp: [%s] grader, albuen %.2f m over basen\n', sprintf('%7.1f', rad2deg(q_opp)), z_albue(q_opp)); %[output:9673ddf3]
fprintf('Albue ned: [%s] grader, albuen %.2f m under basen\n', sprintf('%7.1f', rad2deg(q_ned)), -z_albue(q_ned)); %[output:2912db1f]
% derfor er startgjettet albue opp

%%
%[text] ## 2.i.2 Jacobi-matrisen: fra båndfart til leddfart
% [KI-endret] Leddfart med pinv(J), som i vår Krav2
% J er 6x5: rad 1-3 lineær fart, rad 4-6 vinkelfart, kolonne i = ledd i.
% Regnet i plukkpunktet (1.0, 0, 0.4) fra IK-blokka.
q_p = q_ik(1,:);
J   = Gruppebot.jacob0(q_p) %[output:019a9640]

% J er ikke kvadratisk, så vi bruker pseudoinversen (kap. 8)
qd_p    = pinv(J) * [vb 0 0 0]' %[output:5c5e718b]
v_sjekk = J * qd_p                                  % griperen følger båndet %[output:97dd96a5]
% qd1 = qd5: ledd 5 vrir tilbake det ledd 1 dreier, så eska ikke roterer

% [KI] Singularitet (kap. 8.2): minste singulærverdi, cond og manipulerbarhet
sv      = svd(J)';
Jv      = J(1:3,:);                                 % bare lineær fart
m_p     = sqrt(det(Jv*Jv'));
q_strak = [0 -0.5 0 0.3 0];                         % strak albue, q3 = 0
fprintf('Plukkpunktet: minste singulærverdi %.2f, cond %.1f, manipulerbarhet %.2f\n', sv(end), cond(J), m_p); %[output:6a778501]
fprintf('Strak albue:  minste singulærverdi %.1e (singulær)\n', min(svd(Gruppebot.jacob0(q_strak)))); %[output:02f1ddfc]

% [KI-endret] Hastighetsstyring som i vår Krav2: griperen følger båndet i 2 s bare med J
% For hvert steg: qd = pinv(J)*v og q = q + qd*dt (Euler)
dt_v = 0.02;
q    = Gruppebot.ikine(pose([1.0 -0.3 0.4], 0), 'q0', q_gjett, 'mask', M);
p_start = Gruppebot.fkine(q).t';
for k = 1:round(2/dt_v)
    q = q + (pinv(Gruppebot.jacob0(q)) * [vb 0 0 0]')' * dt_v;
end
p_slutt = Gruppebot.fkine(q).t';
v_avvik = norm(p_slutt - (p_start + 2*vb));         % avstand til eska etter 2 s
fprintf('Hastighetsstyring: %.2f m langs båndet på 2 s, avvik %.1f mm\n', p_slutt(2) - p_start(2), 1000*v_avvik); %[output:1dcb217f]
% avviket kommer fra Euler-steget, dt = 0.01 gir ca. 1 mm

%%
%[text] ## 2.ii.1 Kameraet styrer roboten
% [KI-endret] Som i vår Krav3: måling -> basen -> p + v*t -> ikine
% Eska plukkes der den er etter t = 3.5 s
t_plukk = 3.5;
p_plukk = p_0' + vb*t_plukk;                        % forutsagt posisjon
q_plukk = Gruppebot.ikine(pose(p_plukk, 0), 'q0', q_gjett, 'mask', M);
plukkfeil = norm(Gruppebot.fkine(q_plukk).t' - (p_ekte' + vb*t_plukk));
fprintf('Leddvinkler ved plukk: [%s] grader\n', num2str(rad2deg(q_plukk), '%7.1f')); %[output:3db9dc60]
fprintf('Plukkfeil: %.1f mm (krav < 10 mm), bare fra målefeilen\n', 1000*plukkfeil); %[output:95f06937]

R_kam = SerialLink(Gruppebot, 'name', 'Kamera');    % egen kopi, så andre figurer ikke flytter seg
figure %[output:4d42737b]
R_kam.plot(q_plukk, 'workspace', ws, 'view', vis, 'noname', 'notiles', 'noshadow') %[output:4d42737b]
hold on %[output:4d42737b]
fill3([0.8 1.2 1.2 0.8], [-1.6 -1.6 1.6 1.6], 0.3*[1 1 1 1], [0.7 0.7 0.7])   % båndet %[output:4d42737b]
trplot(eye(4), 'frame', '0', 'length', 0.3, 'rgb') %[output:4d42737b]
trplot(T_C,    'frame', 'C', 'length', 0.3, 'rgb') %[output:4d42737b]
plot3(p_0(1), p_0(2), p_0(3), 'ko', 'MarkerFaceColor', 'y', 'MarkerSize', 8) %[output:4d42737b]
plot3(p_plukk(1), p_plukk(2), p_plukk(3), 'ko', 'MarkerFaceColor', 'g', 'MarkerSize', 8) %[output:4d42737b]
plot3([p_0(1) p_plukk(1)], [p_0(2) p_plukk(2)], [p_0(3) p_plukk(3)], 'k--') %[output:4d42737b]
title('Eske 1: kameraet {C} måler eska (gul), roboten plukker der den er etter 3.5 s (grønn)') %[output:4d42737b]

% [KI-endret] Eske 2 fra vår oppgave_2ii, ligger vridd 20 grader i bildet.
% Samme brennvidde som over, plukk når eska når y = 0.05 m.
y_plukk = 0.05;
uv2     = [405 221];  psi_C2 = deg2rad(20);          % piksel og vinkel i bildet
p_C2    = [(uv2(1) - cx)*Z/fx; (uv2(2) - cy)*Z/fy; Z];
p_02    = h2e(T_C * e2h(p_C2))';                      % p0 = T_C * pC
retning = T_C(1:3,1:3) * [cos(psi_C2); sin(psi_C2); 0];   % eskas retning i {0}
psi2    = atan2(retning(2), retning(1));              % trotx(pi) gir psi = -psi_C
t2      = (y_plukk - p_02(2))/vb(2);                  % tid til eska når y_plukk
p_pl2   = p_02 + vb*t2;
q0      = q_gjett;
q0(1)   = atan2(p_pl2(2) - tx*sin(psi2), p_pl2(1) - tx*cos(psi2));
q0(5)   = q0(1) - psi2;
q_pl2   = Gruppebot.ikine(pose(p_pl2, psi2), 'q0', q0, 'mask', M);
fprintf('Eske 2: målt i [%.3f %.3f %.3f], plukk etter %.2f s i [%.3f %.3f %.3f], psi %.0f grader\n', ... %[output:group:6c643874] %[output:03f2a7ea]
        p_02, t2, p_pl2, rad2deg(psi2)); %[output:group:6c643874] %[output:03f2a7ea]
fprintf('Eske 2: q = [%s] grader, q1 - q5 = %.1f grader\n', sprintf('%7.1f', rad2deg(q_pl2)), rad2deg(q_pl2(1) - q_pl2(5))); %[output:7ef17c1e]

%%
%[text] ## 2.i.4 Baneplanlegging: leddbane mot kartesisk bane
% [KI-endret] jtraj mot ctraj som i vår Krav2, fra plukk til drop på 1.1 m på 2 s (kap. 3 og 7.3)
%  - leddbane: jtraj, femtegradspolynom i hvert ledd (7.3.1)
%  - kartesisk bane: ctraj, rett linje for TCP og ikine i hvert punkt (7.3.2)
dt = 0.02;  t = (0:dt:2)';
q_drop = Gruppebot.ikine(pose([0 1.1 0.4], 0), 'q0', gjett(3,:), 'mask', M);   % drop 1.1 m
Q_ledd = jtraj(q_p, q_drop, t);

pA = Gruppebot.fkine(q_p).t';  pB = [0 1.1 0.4];
s  = tpoly(0, 1, t);                                % 0 -> 1 med null fart i endene, som jtraj
Tc = ctraj(pose(pA, 0).T, pose(pB, 0).T, s);        % poser langs den rette linja
Q_kart = zeros(numel(t), 5);  Q_kart(1,:) = q_p;
for k = 2:numel(t)
    Q_kart(k,:) = Gruppebot.ikine(SE3(Tc(:,:,k)), 'q0', Q_kart(k-1,:), 'mask', M);
end

baner = {Q_ledd, Q_kart};  bnavn = {'Leddbane (jtraj)', 'Kartesisk bane'};
P = cell(1,2);  fart = cell(1,2);  smin = cell(1,2);
u = (pB - pA)/norm(pB - pA);                        % retningen til linja
for b = 1:2 %[output:group:95a4774a]
    Q = baner{b};
    P{b} = zeros(numel(t), 3);  smin{b} = zeros(numel(t), 1);  kond = zeros(numel(t), 1);
    for k = 1:numel(t)
        P{b}(k,:)  = Gruppebot.fkine(Q(k,:)).t';
        Jk         = Gruppebot.jacob0(Q(k,:));
        smin{b}(k) = min(svd(Jk));
        kond(k)    = cond(Jk);
    end
    fart{b}  = [0; vecnorm(diff(P{b}), 2, 2)/dt];
    d        = P{b} - pA;
    avvik_l  = max(vecnorm(d - (d*u')*u, 2, 2));    % avstand fra linja
    leddfart = max(max(abs(diff(Q)/dt)));
    fprintf('%-17s avvik fra rett linje %4.0f mm, maks TCP-fart %.2f m/s, maks leddfart %.2f rad/s, min singulærverdi %.2f, maks cond %.1f, minste q3 %.0f grader\n', ... %[output:3dbb4f81]
            bnavn{b}, 1000*avvik_l, max(fart{b}), leddfart, min(smin{b}), max(kond), rad2deg(min(Q(:,3)))); %[output:3dbb4f81]
end %[output:group:95a4774a]
% Leddbanen er enkel og trenger mindre leddfart, men TCP går i en bue.
% Kartesisk bane går rett, men krever IK i hvert punkt og mer leddfart.
% Begge holder seg langt fra singularitet (q3 > 93 grader).

figure %[output:6d42c061]
% høyden endrer seg bare ca. 1 mm, så banen vises ovenfra
subplot(1,2,1) %[output:6d42c061]
plot(P{1}(:,1), P{1}(:,2), 'b', P{2}(:,1), P{2}(:,2), 'r--', 'LineWidth', 1.5) %[output:6d42c061]
hold on, grid on, axis equal %[output:6d42c061]
plot(pA(1), pA(2), 'ko', 'MarkerFaceColor', 'g') %[output:6d42c061]
plot(pB(1), pB(2), 'ks', 'MarkerFaceColor', 'y') %[output:6d42c061]
xlabel('x [m]'), ylabel('y [m]') %[output:6d42c061]
legend('Leddbane', 'Kartesisk bane', 'Plukk', 'Avlevering', 'Location', 'southwest') %[output:6d42c061]
title('TCP-banen sett ovenfra') %[output:6d42c061]
subplot(1,2,2) %[output:6d42c061]
plot(t, fart{1}, 'b', t, fart{2}, 'r--', 'LineWidth', 1.5), grid on %[output:6d42c061]
xlabel('Tid [s]'), ylabel('TCP-fart [m/s]') %[output:6d42c061]
legend('Leddbane', 'Kartesisk bane', 'Location', 'south') %[output:6d42c061]
title('Fart for griperen') %[output:6d42c061]

%%
%[text] ## Oppsummering (tall til rapporten)
% [KI]
fprintf('\n===== Krav 1 og 2 =====\n'); %[output:0369e7b3]
fprintf('1.i.2/2.i.1  T04 for hånd = toolbox, største avvik %.1e\n', avvik); %[output:9166a245]
