%%
%[text] ## Funksjon
% [KI-endret] Analytisk IK fra vår ik_downward.m, med psi og valg av albue opp eller ned
function q = ik_analytisk(p, psi, L1, L2, d1, L3, tx, tz, albue)
% Griperen rett ned (Corke 7.2.1: 2-leddsarm, pluss base og håndledd)
%   p     = TCP [x y z] i basen
%   psi   = eskas vinkel om z [rad]
%   albue = +1 for albue opp, -1 for albue ned
w  = p(:)' - tx*[cos(psi) sin(psi) 0] + [0 0 L3 + tz];   % håndleddet (origo i ramme 4)
r  = hypot(w(1), w(2));                                  % avstand ut fra basen
h  = d1 - w(3);                                          % positiv når håndleddet er under skulderen
D  = (r^2 + h^2 - L1^2 - L2^2)/(2*L1*L2);                % cos(q3) fra cosinussetningen
assert(abs(D) <= 1 + 1e-10, 'Punktet er utenfor rekkevidden');
q3 = albue*acos(max(-1, min(1, D)));
q2 = atan2(h, r) - atan2(L2*sin(q3), L1 + L2*cos(q3));
q1 = atan2(w(2), w(1));
q4 = -(q2 + q3);                                         % q2 + q3 + q4 = 0 gir griperen rett ned
q5 = atan2(sin(q1 - psi), cos(q1 - psi));                % ledd 5 vrir tilbake det basen dreier
q  = [q1 q2 q3 q4 q5];
end

